                 dict(band='How you use, shape and check them', items=[dict(n=7, label='Open weights and size'), dict(n=8, label='Prompting'), dict(n=9, label='Your knowledge'), dict(n=10, label='When models fail'), dict(n=11, label='Agentic AI')]),
